import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Plugin Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/settings.md","filePath":"configure/settings.md"}'),n={name:"configure/settings.md"};function o(h,e,r,p,l,d){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="plugin-settings" tabindex="-1">Plugin Settings <a class="header-anchor" href="#plugin-settings" aria-label="Permalink to &quot;Plugin Settings&quot;">​</a></h1><p>You may override the default plugin settings by creating a <code>/config/saml-sp.php</code> file.</p><p>View the settings you can override in your project at <code>/vendor/flipboxfactory/saml-sp/src/models/Settings.php</code>. Each setting has a description of what it does and how to customize it.</p><h2 id="entityid" tabindex="-1">EntityID <a class="header-anchor" href="#entityid" aria-label="Permalink to &quot;EntityID&quot;">​</a></h2><p>The Entity ID is the unique ID for the provider (your Craft instance) and defaults to the default site&#39;s base url. There are two Entity ID&#39;s to understand for Service Provider (again, your Craft instance) and these 2 Entity Ids must match to make things work properly.</p><ol><li>System wide Entity ID</li><li>Provider Entity ID</li></ol><h3 id="system-wide-entity-id" tabindex="-1">System Wide Entity ID <a class="header-anchor" href="#system-wide-entity-id" aria-label="Permalink to &quot;System Wide Entity ID&quot;">​</a></h3><p>The system wide Entity ID is the Entity ID of the current environment. You can have multiple environments which will change depending on which environment you&#39;re on (like your base url changes based on the environment).</p><p>Currently, you can edit the EntityID system wide a couple ways.</p><h4 id="_1-add-a-config-file-in-config-saml-sp-php" tabindex="-1">1. Add a config file in <code>config/saml-sp.php</code>. <a class="header-anchor" href="#_1-add-a-config-file-in-config-saml-sp-php" aria-label="Permalink to &quot;1. Add a config file in \`config/saml-sp.php\`.&quot;">​</a></h4><p>This location lives right next to the <code>general.php</code>. Below is an example file contents.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   &#39;entityId&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://my-entity-id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>You can also use environmental variables with Craft parser by passing it as a string.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   &#39;entityId&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;$ENTITY_ID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h4 id="_2-edit-from-the-admin-goto-the-plugin-in-craft-then-click-on-the-settings-menu-item-under-the-plugins-sub-nav" tabindex="-1">2. Edit from the admin (Goto the plugin in craft, then click on the &quot;Settings&quot; menu item under the plugins sub nav). <a class="header-anchor" href="#_2-edit-from-the-admin-goto-the-plugin-in-craft-then-click-on-the-settings-menu-item-under-the-plugins-sub-nav" aria-label="Permalink to &quot;2. Edit from the admin (Goto the plugin in craft, then click on the &quot;Settings&quot; menu item under the plugins sub nav).&quot;">​</a></h4><p>Set the &quot;Default Entity ID&quot; there which will save it to the project config. Environmental variable that can be parsed by the Craft parse can also be set here (ie, $ENTITY_ID).</p><h3 id="provider-entity-id" tabindex="-1">Provider Entity ID <a class="header-anchor" href="#provider-entity-id" aria-label="Permalink to &quot;Provider Entity ID&quot;">​</a></h3><p>Like the system wide Entity ID, there can be multiple providers, possibly one per environment with different configurations. These providers are saved in the database and must be static due to the configuration data share with the IdP. Provider Entity IDs can be modified on the edit page of the provider in the plugin control panel.</p><h2 id="idp-initiated-login" tabindex="-1">IdP-initiated Login <a class="header-anchor" href="#idp-initiated-login" aria-label="Permalink to &quot;IdP-initiated Login&quot;">​</a></h2><p><code>allowIdpInitiatedLogin</code> (default <code>true</code>) accepts logins started at the IdP, such as an app tile on the IdP&#39;s dashboard. These Responses have no <code>InResponseTo</code>.</p><p>A Response that does have <code>InResponseTo</code> must answer an AuthnRequest this site sent within the last hour, and it can only be used once. If every login starts from your site, turn IdP-initiated login off:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/saml-sp.php</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;allowIdpInitiatedLogin&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Outstanding AuthnRequest IDs are stored in Craft&#39;s cache, so load-balanced sites need a shared cache (which Craft already requires).</p><p>The Response must come back to the browser session that sent the AuthnRequest. Session cookies are per host, so a login started on another host than the ACS URL&#39;s is first redirected to the ACS host.</p><h2 id="audience" tabindex="-1">Audience <a class="header-anchor" href="#audience" aria-label="Permalink to &quot;Audience&quot;">​</a></h2><p>Every assertion must have an <code>AudienceRestriction</code> that includes this site&#39;s Entity ID. If logins fail with &quot;not a valid audience&quot; or &quot;no AudienceRestriction&quot;, configure the IdP&#39;s audience (Okta: &quot;Audience URI&quot;; Entra ID: &quot;Identifier (Entity ID)&quot;) to match your Entity ID exactly.</p><p>Entra ID sends the audience as <code>spn:&lt;Entity ID&gt;</code> when the Identifier is the app&#39;s application ID (a bare GUID). That form is accepted automatically.</p><p>If your IdP sends some other audience you can&#39;t change, list it:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/saml-sp.php</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;allowedAudiences&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;urn:example:craft&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Values must match exactly. Only list values the IdP uses for this site alone: an audience it also issues for another application would let that application&#39;s assertions log users in here.</p><h2 id="redirect-after-login" tabindex="-1">Redirect After Login <a class="header-anchor" href="#redirect-after-login" aria-label="Permalink to &quot;Redirect After Login&quot;">​</a></h2><p>After login, the user is sent to the URL in <code>RelayState</code>, but only when it points to this site: a path, or a URL on the current host or any Craft site&#39;s host. Anything else is ignored, and the user goes to Craft&#39;s default post-login URL.</p><p>If your frontend is on a different domain from Craft (for example a headless site), list its host names:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/saml-sp.php</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;allowedRedirectHosts&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;www.example.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Use exact host names, without a scheme or port. Subdomains aren&#39;t included automatically.</p><h2 id="group-configuration-group-assignment" tabindex="-1">Group Configuration/Group Assignment <a class="header-anchor" href="#group-configuration-group-assignment" aria-label="Permalink to &quot;Group Configuration/Group Assignment&quot;">​</a></h2><h3 id="group-attribute-name-group-attribute-mapping" tabindex="-1">Group Attribute Name/Group Attribute Mapping <a class="header-anchor" href="#group-attribute-name-group-attribute-mapping" aria-label="Permalink to &quot;Group Attribute Name/Group Attribute Mapping&quot;">​</a></h3><p>Many IdPs will send groups as an attribute within the SAML Response. When configured, the plugin use that attribute to assign the user to the group properly. To achieve this, add a <code>config/saml-sp.php</code> then use the following configuration.</p><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h4><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // change the value as needed</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;groupAttributeNames&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;groups&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Make sure the value matches the attribute name sent from the IdP.</p><h3 id="auto-create-groups-removed-version-2-3-0" tabindex="-1">Auto-Create Groups Removed (version 2.3.0) <a class="header-anchor" href="#auto-create-groups-removed-version-2-3-0" aria-label="Permalink to &quot;Auto-Create Groups Removed (version 2.3.0)&quot;">​</a></h3><p>Due to the release of Craft CMS 3.5, the project config has become more prevalant. Therefore, we&#39;ve decided to remove the support for <code>autoCreateGroups</code> in version 2.3.0. Production environments shouldn&#39;t be saving user groups when following the project config workflow. This should be done at the lower level environments.</p><p>Please use an event as shown below.</p><h3 id="managing-permissions" tabindex="-1">Managing Permissions <a class="header-anchor" href="#managing-permissions" aria-label="Permalink to &quot;Managing Permissions&quot;">​</a></h3><p>Managing permissions ** is not supported ** automatically. There are a few options on how to manually manage permissions:</p><ol><li>Create the groups before implementing the plugin. Make sure you know all of the groups needed to assign the users properly.</li><li>Use an event! See the <a href="/configure/events.html#assign-user-to-a-user-group-based-on-a-property">EVENT_AFTER_RESPONSE_TO_USER</a> example.</li></ol>`,47)])])}const g=i(n,[["render",o]]);export{c as __pageData,g as default};
